import type { MetadataRoute } from "next";
import { DESIGN_COLORS } from "@/lib/design-colors.generated";

/** Web app manifest: home-screen install on phones. Icons are generated by `pnpm brand:icons`. */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "okinvo",
    short_name: "okinvo",
    description: "Self-hosted invoicing for independent professionals",
    start_url: "/",
    display: "standalone",
    background_color: DESIGN_COLORS.light.canvas,
    theme_color: DESIGN_COLORS.dark.canvas,
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png" },
      {
        src: "/icons/icon-512-maskable.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
